using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceSecondActionLogic_AllCompanions", menuName = "Data/Battle/Logics/Dice Action/Dice Second Action Logic/DiceSecondActionLogic_AllCompanions")]
public class DiceSecondActionLogic_AllCompanions : DiceSecondActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override void OnDrop(ActionFace actionFace, GameObject target, GameObject source)
	{
		if (currentCompanions.ActiveCompanions.Count != 0)
		{
			if (actionFace.SecondActionValue == EffectsValues.NO_VALUE)
			{
				actionFace.SecondBattleAction.AreaCastTarget(currentCompanions.ActiveCompanions, source);
			}
			else
			{
				actionFace.SecondBattleAction.AreaCastTargetAmount(currentCompanions.ActiveCompanions, actionFace.SecondModifiedActionValue, source);
			}
		}
	}
}
